#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct _MagickInfo {
  const char *name;
  const char *decoder;
  const char *encoder;
  const char *mime_type;
  unsigned int thread_support;
} MagickInfo;

static MagickInfo *GetMagickInfo(const char *name, MagickInfo *magick_info) {
  MagickInfo *info = (MagickInfo *)malloc(sizeof(MagickInfo));
  if (!info)
    return NULL;

  info->name = name;
  info->decoder = magick_info->decoder;
  info->encoder = magick_info->encoder;
  info->mime_type = magick_info->mime_type;
  info->thread_support = magick_info->thread_support;
  return info;
}

void SetMagickInfo(MagickInfo *magick_info, const char *name, const char *decoder, const char *encoder,
                   const char *mime_type, unsigned int thread_support) {
  magick_info->name = name;
  magick_info->decoder = decoder;
  magick_info->encoder = encoder;
  magick_info->mime_type = mime_type;
  magick_info->thread_support = thread_support;
}

size_t RegisterMagickInfo(MagickInfo *magick_info) {
  size_t size = sizeof(MagickInfo);
  return size;
}

size_t RegisterJPEGImage(void) {
  static const MagickInfo jpeg_info = {
      "JPEG", "JPEGDecoder", "JPEGEncoder", "image/jpeg", 1};

  size_t total_size = 0;
  const char *identifiers[] = {"JPE", "JPEG", "JPG", "JPS", "PJPEG"};
  int num_identifiers = sizeof(identifiers) / sizeof(identifiers[0]);

  for (int i = 0; i < num_identifiers; i++) {
    MagickInfo *entry = GetMagickInfo((char *)identifiers[i], &jpeg_info);
    if (!entry)
      continue;

    total_size += RegisterMagickInfo(entry);
  }

  return total_size;
}
